/// Returns the index of the last position whose value is <= `elem`,
/// or -1 if all values are > `elem`.
///
/// Preconditions (as given by the problem statement):
/// - `v` is sorted nondecreasing
/// - 0 <= c <= f + 1 <= v.len()
/// - for all i < c: v[i] <= elem
/// - for all i > f: v[i] > elem
///
/// Postcondition:
/// - -1 <= p < v.len()
/// - for all i <= p: v[i] <= elem
/// - for all i >  p: v[i] >  elem
///
/// The measure (f - c + 1) strictly decreases on each recursive call.
pub fn binary_search_recursive(v: &[i32], elem: i32, c: isize, f: isize) -> isize {
    // Base case: unresolved interval is empty (c > f).
    // Given the invariants, everything > f is > elem, so the last <= elem is f.
    if c > f {
        return f;
    }

    // Safe midpoint computation in isize, then cast to usize for indexing.
    let mid: isize = c + (f - c) / 2;
    let mid_usize = mid as usize;

    if v[mid_usize] <= elem {
        // mid itself is valid (<= elem), so answer is in [mid+1 .. f] or mid.
        // New interval size: f - (mid+1) + 1 = f - mid, strictly smaller than f - c + 1.
        binary_search_recursive(v, elem, mid + 1, f)
    } else {
        // v[mid] > elem, so answer is in [c .. mid-1].
        // New interval size: (mid-1) - c + 1 = mid - c, strictly smaller than f - c + 1.
        binary_search_recursive(v, elem, c, mid - 1)
    }
}

